    /**
     * Call Harvester API with pagination support for a single page (Only GET calls)
     * Returns the response data along with the continue token for manual pagination control
     * @param baseUrl The base URL without pagination parameters
     * @param token The API token
     * @param continueToken The continue token from previous call (null for first page)
     * @param pageSize The number of items per page (default 50)
     * @return ServiceResponse with data.items, data.metadata.continue, and data.metadata.remainingItemCount
     */
    static ServiceResponse callApiWithPagination(String baseUrl, String token, String continueToken = null, int pageSize = 50) {
        def client = new HttpApiClient()
        RequestOptions opts = new RequestOptions()
        opts.apiToken = token
        opts.ignoreSSL = true

        // Build URL with pagination parameters
        String paginatedUrl = baseUrl

        // Add limit parameter
        String separator = baseUrl.contains('?') ? '&' : '?'
        paginatedUrl += "${separator}limit=${pageSize}"

        // Add continue token if provided
        if (continueToken && !continueToken.isEmpty()) {
            paginatedUrl += "&continue=${continueToken}"
        }

        log.debug "Making paginated API call: ${paginatedUrl}"

        // Make the API call
        ServiceResponse response = client.callJsonApi(paginatedUrl, null, opts, 'GET')

        if (!response.success) {
            log.error "Paginated API call failed: ${response.msg}"
            return response
        }

        // Parse response data
        def responseData = response.data
        if (responseData instanceof String) {
            def jsonSlurper = new JsonSlurper()
            responseData = jsonSlurper.parseText(responseData)
        }

        // Extract continue token and remaining count
        def nextContinueToken = responseData?.metadata?.continue ?: ""
        def remainingItemCount = responseData?.metadata?.remainingItemCount ?: 0
        def currentItems = responseData?.items ?: []

        log.info "Page completed: ${currentItems.size()} items, continue token: ${nextContinueToken ? 'present' : 'none'}, remaining: ${remainingItemCount}"

        // Return response with pagination metadata
        return new ServiceResponse(
                success: true,
                data: [
                        kind: responseData?.kind,
                        apiVersion: responseData?.apiVersion,
                        metadata: [
                                resourceVersion: responseData?.metadata?.resourceVersion,
                                continue: nextContinueToken,
                                remainingItemCount: remainingItemCount,
                                currentPageSize: currentItems.size()
                        ],
                        items: currentItems
                ]
        )
    }

