    /**
     * Make a DELETE request to the Harvester API
     * @param url The base URL
     * @param path The API path
     * @param token The API token
     * @param body Optional request body for DELETE operations
     * @return ServiceResponse
     */
    static ServiceResponse delete(String url, String path, String token, def body = null, Map queryParams = null) {
        // Safety check: Prevent accidental "delete all" on collections
        if (isBulkDeleteWithoutSelector(path, queryParams)) {
            log.error "Blocked potential accidental bulk delete on ${path}"
            return new ServiceResponse(success: false, msg: "Bulk delete without selector is not allowed for safety.")
