        return response
    }

    /**
     * Checks if a namespace/project is a system namespace that should be filtered out
     * @param projectName The name of the project/namespace
     * @return true if it's a system namespace, false otherwise
     */
    static boolean isSystemNamespace(String projectName) {
        if (!projectName) return true

        // Check exact matches
        if (HarvesterConstants.SYSTEM_NAMESPACES.contains(projectName)) {
            return true
        }

        // Check for common system namespace patterns (Kubernetes, Harvester, Longhorn, Rancher)
        if (HarvesterConstants.SYSTEM_NAMESPACE_PREFIXES.any { projectName.startsWith(it) }) {
            return true
        }
        return projectName ==~ HarvesterConstants.RANCHER_GENERATED_NAMESPACE_REGEX
    }

    /**
     * Checks if the delete operation is a bulk delete without selectors
     * @param path The API path
     * @param queryParams The query parameters
     * @return true if it's a bulk delete without selectors
     */
    private static boolean isBulkDeleteWithoutSelector(String path, Map queryParams) {
        boolean hasSelectors = queryParams != null && (queryParams.containsKey('labelSelector') || queryParams.containsKey('fieldSelector'))
        if (hasSelectors) {
            return false
        }

        // Check if path targets a collection
        // Remove trailing slash
        String cleanPath = path.endsWith('/') ? path.substring(0, path.length() - 1) : path
        String lastSegment = cleanPath.substring(cleanPath.lastIndexOf('/') + 1)

        // List of known resource collections
        def collections = [
                'virtualmachines',
                'virtualmachineinstances',
                'datavolumes',
                'persistentvolumeclaims',
                'secrets',
                'configmaps',
                'pods',
                'services',
                'nodes',
                'projects',
                'namespaces',
                'events',
                'serviceaccounts',
                'roles',
                'rolebindings',
                'clusterroles',
                'clusterrolebindings'
        ]

        return collections.any { it == lastSegment }
    }
